use catalog::catalog::{lookup, LookupError};
use catalog::consumer::{describe, total};

#[test]
fn lookups_totals_and_descriptions_carry_typed_errors() {
    let missing = |key: &str| LookupError::Missing { key: key.into() };
    assert_eq!(lookup("apple"), Ok(3));
    assert_eq!(lookup("pear"), Ok(7));
    assert_eq!(
        lookup("offline"),
        Err(LookupError::Unavailable { retryable: true })
    );
    assert_eq!(lookup("kiwi"), Err(missing("kiwi")));
    assert_eq!(lookup(""), Err(missing("")));
    assert_eq!(total(&[]), Ok(0));
    assert_eq!(total(&["apple", "pear", "apple"]), Ok(13));
    assert_eq!(total(&["apple", "kiwi", "offline"]), Err(missing("kiwi")));
    assert_eq!(
        total(&["offline", "kiwi"]),
        Err(LookupError::Unavailable { retryable: true })
    );
    assert_eq!(describe("pear"), "pear=7");
    assert_eq!(describe("kiwi"), "missing:kiwi");
    assert_eq!(describe("offline"), "unavailable:retryable=true");
}

