package fixture

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"reflect"
	"strings"
	"testing"
)

func TestHandlerFiltersAndPaginates(t *testing.T) {
	items := []Item{{ID: 3, Kind: "a"}, {ID: 1, Kind: "b"}, {ID: 4, Kind: "a"}, {ID: 2, Kind: "a"}}
	before := append([]Item(nil), items...)
	cases := []struct {
		query  string
		status int
		ids    []int
	}{
		{"", http.StatusOK, []int{3, 1, 4, 2}},
		{"kind=a", http.StatusOK, []int{3, 4, 2}},
		{"kind=", http.StatusOK, []int{3, 1, 4, 2}},
		{"kind=A", http.StatusOK, []int{}},
		{"kind=a&offset=1&limit=1", http.StatusOK, []int{4}},
		{"offset=4", http.StatusOK, []int{}},
		{"offset=9", http.StatusOK, []int{}},
		{"limit=0", http.StatusOK, []int{}},
		{"limit=9", http.StatusOK, []int{3, 1, 4, 2}},
		{"sort=id&page=2", http.StatusOK, []int{3, 1, 4, 2}},
		{"offset=x", http.StatusBadRequest, nil},
		{"limit=x", http.StatusBadRequest, nil},
		{"offset=", http.StatusBadRequest, nil},
		{"limit=", http.StatusBadRequest, nil},
		{"offset=-1", http.StatusBadRequest, nil},
		{"limit=-1", http.StatusBadRequest, nil},
		{"limit=99999999999999999999", http.StatusBadRequest, nil},
		{"offset=99999999999999999999", http.StatusBadRequest, nil},
	}
	for _, c := range cases {
		rec := httptest.NewRecorder()
		Handler(items).ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/items?"+c.query, nil))
		if rec.Code != c.status {
			t.Fatalf("%q: status %d, want %d", c.query, rec.Code, c.status)
		}
		if c.status != http.StatusOK {
			continue
		}
		if got := rec.Header().Get("Content-Type"); got != "application/json" {
			t.Fatalf("%q: content type %q", c.query, got)
		}
		var got []Item
		if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
			t.Fatalf("%q: %v", c.query, err)
		}
		ids := []int{}
		for _, item := range got {
			ids = append(ids, item.ID)
		}
		if !reflect.DeepEqual(ids, c.ids) {
			t.Fatalf("%q: ids %v, want %v", c.query, ids, c.ids)
		}
	}
	if !reflect.DeepEqual(items, before) {
		t.Fatalf("caller items changed: %v", items)
	}
	rec := httptest.NewRecorder()
	Handler(nil).ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/items", nil))
	if body := strings.TrimSpace(rec.Body.String()); body != "[]" {
		t.Fatalf("nil items: body %q", body)
	}
}

