package fixture

import (
	"reflect"
	"testing"
)

func TestRecordContractAndFollowUps(t *testing.T) {
	lines := []string{"  alpha ", "", "\t", "beta", " gamma\t", "beta  ", " alpha"}
	before := append([]string(nil), lines...)
	records := Produce(lines)
	want := []Record{{ID: 1, Text: "alpha"}, {ID: 4, Text: "beta"}, {ID: 5, Text: "gamma"}, {ID: 6, Text: "beta"}, {ID: 7, Text: "alpha"}}
	if !reflect.DeepEqual(records, want) {
		t.Fatalf("Produce: %v, want %v", records, want)
	}
	if got := Produce(nil); len(got) != 0 {
		t.Fatalf("Produce(nil): %#v", got)
	}
	if got := Consume(records); !reflect.DeepEqual(got, []string{"1:alpha", "4:beta", "5:gamma", "6:beta", "7:alpha"}) {
		t.Fatalf("Consume: %q", got)
	}
	if !reflect.DeepEqual(records, want) {
		t.Fatalf("Consume changed its input: %v", records)
	}
	if got := Consume([]Record{{ID: 9, Text: "x"}, {ID: 2, Text: "x"}}); !reflect.DeepEqual(got, []string{"9:x", "2:x"}) {
		t.Fatalf("Consume order: %q", got)
	}
	if got := Consume(nil); len(got) != 0 {
		t.Fatalf("Consume(nil): %#v", got)
	}
	if kept, dropped := Stats(lines); kept != 5 || dropped != 2 {
		t.Fatalf("Stats: kept %d, dropped %d", kept, dropped)
	}
	if kept, dropped := Stats([]string{"", " \t "}); kept != 0 || dropped != 2 {
		t.Fatalf("Stats of blanks: kept %d, dropped %d", kept, dropped)
	}
	if got := Duplicates(lines); !reflect.DeepEqual(got, []string{"alpha", "beta"}) {
		t.Fatalf("Duplicates: %q", got)
	}
	if got := Duplicates([]string{"a", " ", "b", ""}); len(got) != 0 {
		t.Fatalf("Duplicates without repeats: %#v", got)
	}
	if !reflect.DeepEqual(lines, before) {
		t.Fatalf("input changed: %q", lines)
	}

	cases := []struct {
		line string
		id   int
		text string
		ok   bool
	}{
		{"7:alpha", 7, "alpha", true},
		{"12:  two words \t", 12, "two words", true},
		{"3:a:b", 3, "a:b", true},
		{"007:x", 7, "x", true},
		{"0:x", 0, "", false},
		{"000:x", 0, "", false},
		{"-1:x", 0, "", false},
		{"+1:x", 0, "", false},
		{" 1:x", 0, "", false},
		{"1 :x", 0, "", false},
		{"1:", 0, "", false},
		{"1: \t", 0, "", false},
		{":x", 0, "", false},
		{"x1:y", 0, "", false},
		{"alpha", 0, "", false},
		{"", 0, "", false},
		{"99999999999999999999:x", 0, "", false},
	}
	for _, c := range cases {
		if id, text, ok := Parse(c.line); id != c.id || text != c.text || ok != c.ok {
			t.Fatalf("Parse(%q): %d %q %v", c.line, id, text, ok)
		}
	}
	ids := []string{"4:d", "bad", "2:b", "0:z", "4:again", ""}
	original := append([]string(nil), ids...)
	if got := IDs(ids); !reflect.DeepEqual(got, []int{4, 2, 4}) {
		t.Fatalf("IDs: %v", got)
	}
	if !reflect.DeepEqual(ids, original) {
		t.Fatalf("IDs changed its input: %q", ids)
	}
	if got := IDs([]string{"bad", "0:z"}); len(got) != 0 {
		t.Fatalf("IDs without valid lines: %#v", got)
	}
}

